; ============================================================================
; tiles_fx — 8x8 background tileset (WazHack/ZX side-view scene)
; Generated by tools/gfx_convert.py on 2026-09-24
; Source        : assets/gfx/sprites/grid/tiles_fx.grid
;                 DRAFT: assets/gfx/source/draft3_frames.html
; Layout        : 2 tiles x 8 bitmap bytes (MSB=left), row-major
;                 parallel attr table, one attribute byte per tile
; Clash         : each tile is one paper+ink — clash-legal by construction
; Intended use  : Wizard CAST2 bolt: ZAP1/ZAP2 alternate per tick in the gap cells on the staff row (body cell row 2; bolt joins on in-cell row 5 = frame row 21, CAST2 staff hand)
; ============================================================================
tiles_fx:
tiles_fx_zap1:
        DEFB $00,$00,$00,$18,$24,$C3,$04,$00    ; zap1
tiles_fx_zap2:
        DEFB $00,$00,$40,$00,$00,$C3,$24,$18    ; zap2

tiles_fx_attr:
        DEFB $45    ; zap1     ink=cyan paper=black bright=1
        DEFB $45    ; zap2     ink=cyan paper=black bright=1
tiles_fx_count EQU 2
